// CSV rows (rota, level, staff_id) → { oncall: { afterHours: [ids…], businessHours: [ids…] } }.
const csv = String($input.first().json.data ?? '').trim();
const [header, ...lines] = csv.split(/\r?\n/).map((l) => l.split(',').map((c) => c.trim().replace(/^"|"$/g, '')));
const col = (name) => header.indexOf(name);
const ladders = { after_hours: [], business_hours: [] };
for (const cells of lines) {
  const rota = cells[col('rota')];
  const level = Number(cells[col('level')]);
  const staffId = cells[col('staff_id')];
  if (!ladders[rota] || !staffId || !Number.isInteger(level)) continue;
  ladders[rota][level - 1] = staffId;
}
for (const [rota, ids] of Object.entries(ladders)) {
  // [...ids] turns holes (a missing level) into undefined — .some() alone would skip them
  if (!ids.length || [...ids].some((id) => !id)) throw new Error(`On-call rota "${rota}" is empty or has a gap — refusing to sync`);
}
const payload = { oncall: { afterHours: ladders.after_hours, businessHours: ladders.business_hours } };
return [{ json: { payload: JSON.stringify(payload) } }];
